(()=>{'use strict';const m=location.pathname.match(/^\/profiles\/([^/]+)\/$/);if(!m)return;const id=decodeURIComponent(m[1]),main=document.querySelector('main');if(!/^FR-[A-Z0-9]+-[A-Za-z0-9][A-Za-z0-9._-]{2,100}$/.test(id))return;const API='https://franklin-navigator-membership.onrender.com';const n=(t,x,c)=>{const e=document.createElement(t);if(x!==undefined)e.textContent=x;if(c)e.className=c;return e};const safe=v=>{try{const u=new URL(String(v||''));return u.protocol==='https:'&&!u.username&&!u.password?u:null}catch{return null}};const lines=v=>String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const competitorCards=()=>[...document.querySelectorAll('.hf35-competitor-card')];function addAction(label,value){const u=safe(value);if(!u)return;const box=document.querySelector('.profile-primary-actions');if(!box||[...box.querySelectorAll('a')].some(a=>a.href===u.href))return;const a=n('a',label,'button');a.href=u.href;a.rel='noopener noreferrer ugc';box.append(a)}function insertBadge(){const h=document.querySelector('.r22-profile-hero h1');if(!h||document.querySelector('.hf35-member-badge'))return;const b=n('span','Community Member','hf35-member-badge');h.insertAdjacentElement('beforebegin',b)}function navFor(ids){if(ids.length<3||document.querySelector('.hf35-profile-section-nav'))return;const nav=n('nav','', 'hf35-profile-section-nav');nav.setAttribute('aria-label','Profile sections');for(const [id,label] of ids){const a=n('a',label);a.href='#'+id;nav.append(a)}document.querySelector('.r22-profile-hero')?.insertAdjacentElement('afterend',nav)}async function run(){try{const l=await fetch('/data/public-profile-suppressions.json',{cache:'no-store'});if(!l.ok)throw 0;const d=await l.json();if((d.entries||[]).some(e=>e&&e.profileId===id&&e.status==='SUPPRESSED')){document.title='Profile unavailable | Franklin Navigator';if(main){main.innerHTML='<section class="section"><div class="wrap narrow"><h1>This profile is not publicly displayed.</h1><p>This profile has been removed from Franklin Navigator public view.</p></div></section>'}return}}catch{if(main){main.innerHTML='<section class="section"><div class="wrap narrow"><h1>This profile is temporarily unavailable.</h1><p>Franklin Navigator could not verify the public-display status of this profile. Please try again shortly.</p></div></section>'}return}let out;try{const r=await fetch(API+'/api/member/public-profile?profileId='+encodeURIComponent(id),{credentials:'omit',cache:'no-store'});if(!r.ok)return;out=await r.json()}catch{return}if(out.activePaidMember===true){competitorCards().forEach(x=>x.remove());document.body.dataset.activeMember='true';insertBadge()}const p=out.publication;if(!p||p.profileId!==id||p.provenance!=='MEMBER_SUBMITTED_REVIEWED')return;const f=p.fields||{};addAction('Website',f.website);addAction('Contact',f.contactUrl);addAction('Book',f.bookingUrl);addAction('Get a quote',f.quoteUrl);addAction('Menu',f.menuUrl);addAction('Order',f.orderUrl);addAction('Directions',f.directionsUrl);const image=safe(f.profileImageUrl);if(image){const av=document.querySelector('.profile-avatar');if(av){av.textContent='';const img=document.createElement('img');img.src=image.href;img.alt='';av.append(img)}}const article=document.querySelector('.r22-profile-layout>article');if(!article)return;const anchor=article.querySelector('#sources')||article.querySelector('#manage');const blocks=[];function mod(id,label,value){if(!String(value||'').trim())return;const s=n('section','', 'hf35-member-module');s.id=id;s.append(n('h2',label),n('p',String(value).trim()));blocks.push(s)}mod('member-about','About',f.summary);mod('member-services','Services & specialties',f.services);const details=[['Hours',f.hours],['Service area',f.serviceArea],['Pricing & payment',f.pricing],['Languages',f.languages],['Accessibility',f.accessibility]].filter(x=>String(x[1]||'').trim());if(details.length){const s=n('section','', 'hf35-member-module');s.id='member-details';s.append(n('h2','Details'));const g=n('div','', 'hf35-member-grid');details.forEach(([a,b])=>{const c=n('div','', 'card');c.append(n('strong',a),n('p',b));g.append(c)});s.append(g);blocks.push(s)}[['member-experience','Experience',f.experience],['member-credentials','Credentials & certifications',f.credentials],['member-awards','Awards & honors',f.awards],['member-associations','Associations',f.associations],['member-education','Education & training',f.education],['member-publications','Publications, media & speaking',f.publications],['member-offers','Offers & events',f.offersEvents]].forEach(x=>mod(...x));const gallery=lines(f.galleryUrls).map(safe).filter(Boolean).slice(0,8);if(gallery.length){const s=n('section','', 'hf35-member-module');s.id='member-gallery';s.append(n('h2','Photos'));const g=n('div','', 'hf35-member-gallery');gallery.forEach(u=>{const i=document.createElement('img');i.src=u.href;i.alt='';i.loading='lazy';g.append(i)});s.append(g);blocks.push(s)}const social=lines(f.socialLinks).map(safe).filter(Boolean).slice(0,12);if(social.length){const s=n('section','', 'hf35-member-module');s.id='member-online';s.append(n('h2','Online presence'));const g=n('div','', 'hf35-online');social.forEach(u=>{const a=n('a',u.hostname.replace(/^www\./,''),'button');a.href=u.href;a.rel='noopener noreferrer ugc';g.append(a)});s.append(g);blocks.push(s)}for(const b of blocks){if(anchor)article.insertBefore(b,anchor);else article.append(b)}const navIds=[];if(document.querySelector('#about'))navIds.push(['about','Overview']);for(const b of blocks)navIds.push([b.id,b.querySelector('h2')?.textContent||'Details']);if(document.querySelector('#sources'))navIds.push(['sources','Sources']);if(document.querySelector('#manage'))navIds.push(['manage','Manage']);navFor(navIds)}run()})();